import math

def rows(conn,sql,args=()):
    with conn.cursor() as c:c.execute(sql,args);return c.fetchall()

def validate(conn,policy):
    if not conn.get_autocommit() or conn.server_status&1:raise ValueError('clean autocommit connection required')
    if not isinstance(policy,dict) or set(policy)!={'max_bytes','max_transaction_seconds','max_pending_mdl','lock_timeout_seconds'}:raise ValueError('exact admission policy required')
    if type(policy['max_bytes']) is not int or policy['max_bytes']<1 or type(policy['max_pending_mdl']) is not int or not 0<=policy['max_pending_mdl']<=10:raise ValueError('bounded bytes and pending lock budget')
    age=policy['max_transaction_seconds']
    if type(age) not in (int,float) or (type(age) is float and not math.isfinite(age)) or age<0 or type(policy['lock_timeout_seconds']) is not int or not 1<=policy['lock_timeout_seconds']<=3:raise ValueError('age and DDL lock timeout')

def inspect(conn,policy):
    validate(conn,policy)
    size=rows(conn,"SELECT DATA_LENGTH+INDEX_LENGTH FROM information_schema.tables WHERE TABLE_SCHEMA='training' AND TABLE_NAME='invoice_events'")
    if not size or size[0][0] is None:raise ValueError('approved table absent')
    footprint=int(size[0][0])
    blockers=rows(conn,"SELECT DISTINCT t.PROCESSLIST_ID,TIMESTAMPDIFF(MICROSECOND,i.trx_started,NOW(6))/1000000 FROM performance_schema.metadata_locks m JOIN performance_schema.threads t ON t.THREAD_ID=m.OWNER_THREAD_ID JOIN information_schema.innodb_trx i ON i.trx_mysql_thread_id=t.PROCESSLIST_ID WHERE m.OBJECT_SCHEMA='training' AND m.OBJECT_NAME='invoice_events' AND m.OBJECT_TYPE='TABLE' AND m.LOCK_STATUS='GRANTED' AND t.PROCESSLIST_ID<>CONNECTION_ID() ORDER BY t.PROCESSLIST_ID")
    pending=int(rows(conn,"SELECT COUNT(*) FROM performance_schema.metadata_locks WHERE OBJECT_SCHEMA='training' AND OBJECT_NAME='invoice_events' AND OBJECT_TYPE='TABLE' AND LOCK_STATUS='PENDING' AND OWNER_THREAD_ID<>(SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_ID=CONNECTION_ID())")[0][0])
    oldest=max((float(age) for _,age in blockers),default=0.0)
    reasons=[]
    if 2*footprint>policy['max_bytes']:reasons.append('space_budget')
    if blockers and oldest>policy['max_transaction_seconds']:reasons.append('old_transaction')
    if pending>policy['max_pending_mdl']:reasons.append('pending_mdl')
    return {'footprint_bytes':footprint,'required_bytes':2*footprint,'blocking_connections':[int(pid) for pid,_ in blockers],'oldest_seconds':oldest,'pending_mdl':pending,'admitted':not reasons,'reasons':reasons}

def apply(conn,policy,after_precheck=None):
    evidence=inspect(conn,policy)
    if not evidence['admitted']:raise ValueError('DDL admission refused: '+','.join(evidence['reasons']))
    index=rows(conn,"SELECT COLUMN_NAME,SEQ_IN_INDEX,NON_UNIQUE,SUB_PART,COLLATION,IS_VISIBLE,INDEX_TYPE FROM information_schema.statistics WHERE TABLE_SCHEMA='training' AND TABLE_NAME='invoice_events' AND INDEX_NAME='idx_state_created' ORDER BY SEQ_IN_INDEX")
    if index:
        if index!=(('state',1,1,None,'A','YES','BTREE'),('created_at',2,1,None,'A','YES','BTREE')):raise ValueError('occupied index name has incompatible definition')
        return {'changed':False,'index':'idx_state_created'}
    previous=rows(conn,'SELECT @@SESSION.lock_wait_timeout')[0][0]
    try:
        rows(conn,'SET SESSION max_execution_time=%s',(policy['lock_timeout_seconds'],))
        if after_precheck is not None:after_precheck()
        rows(conn,'ALTER TABLE training.invoice_events ADD INDEX idx_state_created(state,created_at), ALGORITHM=INPLACE, LOCK=NONE')
    finally:rows(conn,'SET SESSION max_execution_time=%s',(previous,))
    return {'changed':True,'index':'idx_state_created'}

